204	func appendUnique(existing []string, values ...string) []string {
205		if len(values) == 0 {
206			return existing
207		}
208	
209		seen := make(map[string]struct{}, len(existing)+len(values))
210		for _, value := range existing {
211			seen[value] = struct{}{}
212		}
213		for _, value := range values {
214			if _, ok := seen[value]; ok {
215				continue
216			}
217			seen[value] = struct{}{}
218			existing = append(existing, value)
219		}
220	
221		return existing
222	}
